const scriptUrl=document.currentScript?.src||new URL('assets/app.js',document.baseURI).href;
const siteRoot=new URL('../',scriptUrl);
if(!document.querySelector('link[href*="coach.css"]')){const coachStyles=document.createElement('link');coachStyles.rel='stylesheet';coachStyles.href=new URL('coach.css?v=2026102104',scriptUrl).href;document.head.appendChild(coachStyles);}
const routes={
  Hiragana:{course:'hiragana',title:'Hiragana',href:'learn/hiragana/',reason:'Build instant sound-to-character recognition before adding vocabulary and grammar.'},
  Katakana:{course:'katakana',title:'Katakana',href:'learn/katakana/',reason:'Make loanword reading automatic, then move into foundational vocabulary.'},
  Foundation:{course:'foundation_grammar_reading',title:'Foundation Grammar & Reading',href:'learn/grammar-reading/',reason:'Connect essential words to complete Japanese sentence patterns.'},
  N5:{course:'n5_grammar_reading',title:'N5 Grammar & Reading',href:'learn/n5/grammar-reading/',reason:'Build reliable beginner sentence processing with N5 grammar and reading.'},
  N4:{course:'n4_grammar_reading',title:'N4 Grammar & Reading',href:'learn/n4/grammar-reading/',reason:'Strengthen connected sentences and elementary reading speed.'},
  N3:{course:'n3_grammar_reading',title:'N3 Grammar & Reading',href:'learn/n3/grammar-reading/',reason:'Bridge into intermediate Japanese with faster grammar recognition.'},
  N2:{course:'n2_grammar_reading',title:'N2 Grammar & Reading',href:'learn/n2/grammar-reading/',reason:'Train upper-intermediate accuracy and detailed reading.'},
  N1:{course:'n1_grammar_reading',title:'N1 Grammar & Reading',href:'learn/n1/grammar-reading/',reason:'Practice advanced vocabulary and nuanced sentence comprehension.'}
};
const courseRoutes={
  hiragana:{title:'Hiragana',href:'learn/hiragana/'},katakana:{title:'Katakana',href:'learn/katakana/'},basic_words:{title:'Basic Words',href:'learn/basic-words/'},foundation_grammar_reading:{title:'Foundation Grammar & Reading',href:'learn/grammar-reading/'},
  n5_kanji:{title:'N5 Kanji',href:'learn/n5/kanji/'},n5_vocabulary:{title:'N5 Vocabulary',href:'learn/n5/vocabulary/'},n5_grammar_reading:{title:'N5 Grammar & Reading',href:'learn/n5/grammar-reading/'},
  n4_kanji:{title:'N4 Kanji',href:'learn/n4/kanji/'},n4_vocabulary:{title:'N4 Vocabulary',href:'learn/n4/vocabulary/'},n4_grammar_reading:{title:'N4 Grammar & Reading',href:'learn/n4/grammar-reading/'},
  n3_kanji:{title:'N3 Kanji',href:'learn/n3/kanji/'},n3_vocabulary:{title:'N3 Vocabulary',href:'learn/n3/vocabulary/'},n3_grammar_reading:{title:'N3 Grammar & Reading',href:'learn/n3/grammar-reading/'},
  n2_kanji:{title:'N2 Kanji',href:'learn/n2/kanji/'},n2_vocabulary:{title:'N2 Vocabulary',href:'learn/n2/vocabulary/'},n2_grammar_reading:{title:'N2 Grammar & Reading',href:'learn/n2/grammar-reading/'},
  n1_kanji:{title:'N1 Kanji',href:'learn/n1/kanji/'},n1_vocabulary:{title:'N1 Vocabulary',href:'learn/n1/vocabulary/'},n1_grammar_reading:{title:'N1 Grammar & Reading',href:'learn/n1/grammar-reading/'}
};
// Ported from DraMap's LearningHubController placement bank.
const placementQuestions=[
  {level:'Hiragana',skill:'reading',prompt:"Which character is 'a'?",context:'あ',answer:'あ',choices:['あ','お','め','ぬ']},
  {level:'Katakana',skill:'reading',prompt:"Which character is 'a'?",context:'ア',answer:'ア',choices:['ア','オ','マ','ヌ']},
  {level:'Foundation',skill:'vocabulary',prompt:'What does this mean?',context:'おとうさん',answer:'father',choices:['father','teacher','school','friend']},
  {level:'N5',skill:'kanji',prompt:'What does this kanji mean?',context:'山',answer:'mountain',choices:['mountain','river','book','person']},
  {level:'N4',skill:'vocabulary',prompt:'What does this word mean?',context:'準備',answer:'preparation',choices:['preparation','promise','explanation','experience']},
  {level:'N3',skill:'grammar',prompt:'Choose the best expression',context:'雨が降り___です。',answer:'そう',choices:['そう','しか','ほど','まで']},
  {level:'N2',skill:'vocabulary',prompt:'What does this word mean?',context:'維持',answer:'maintenance',choices:['maintenance','release','criticism','movement']},
  {level:'N1',skill:'vocabulary',prompt:'What does this word mean?',context:'騒動',answer:'disturbance',choices:['disturbance','silence','agreement','custom']}
];
const routesOrder=['Hiragana','Katakana','Foundation','N5','N4','N3','N2','N1'];
function defaultState(){return{version:2,profile:null,assessment:null,sessions:[],lastCourse:null,learning:{records:[],courses:{},streak:{count:0,lastDate:null}}};}
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(!saved||saved.version!==2)return defaultState();const state={...defaultState(),...saved};state.learning={...defaultState().learning,...(saved.learning||{})};state.learning.records=Array.isArray(state.learning.records)?state.learning.records:[];state.learning.courses=state.learning.courses||{};return state;}catch(_){return defaultState();}}
function saveState(state){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(_){}}
function absolute(href){return new URL(href,siteRoot).href;}
function routeForCourse(courseId){const route=courseRoutes[courseId];return route?{course:courseId,...route,reason:'A scheduled review is ready before this memory fades.'}:null;}
function dueRecords(state){const now=Date.now();return (state.learning?.records||[]).filter(record=>record.dueAt&&record.dueAt<=now).sort((a,b)=>a.dueAt-b.dueAt);}
function weakestSkill(state){const totals={};Object.entries(state.assessment?.skills||{}).forEach(([skill,value])=>{totals[skill]={attempts:value.total||0,correct:value.correct||0};});Object.values(state.learning?.courses||{}).forEach(course=>Object.entries(course.skills||{}).forEach(([skill,value])=>{const total=totals[skill]||(totals[skill]={attempts:0,correct:0});total.attempts+=value.attempts||0;total.correct+=value.correct||0;}));return Object.entries(totals).filter(([,value])=>value.attempts>0&&value.correct/value.attempts<.85).sort((a,b)=>(a[1].correct/a[1].attempts)-(b[1].correct/b[1].attempts)||b[1].attempts-a[1].attempts)[0]||null;}
function recommendedRoute(state){const due=dueRecords(state)[0],reviewRoute=due&&routeForCourse(due.courseId);if(reviewRoute)return{...reviewRoute,reason:'A scheduled '+due.skill+' review is ready now.',mode:'review'};return routes[state.assessment?.estimatedLevel]||routes.Hiragana;}
function todayMinutes(state){return Number(state.profile?.minutes||10);}
function daysSince(iso){return iso?Math.floor((Date.now()-new Date(iso).getTime())/86400000):999;}
function dailyPlan(state){const route=recommendedRoute(state),due=dueRecords(state),weak=weakestSkill(state),last=(state.sessions||[]).slice(-1)[0],comeback=daysSince(last?.completedAt)>=2,minutes=comeback?3:todayMinutes(state),weakLabel=weak?weak[0].replace(/^./,letter=>letter.toUpperCase()):null;return{route,due,weak,minutes,comeback,why:comeback?'A three-minute restart lowers the barrier. Finishing today matters more than catching up.':due.length?'This review is due now. Returning before it fades will save time later.':weakLabel?'Your '+weakLabel.toLowerCase()+' result is the current bottleneck, so today keeps it in focus.':'This course matches your current level and keeps the next step small.',steps:[{label:due.length?'Review':'Warm up',minutes:Math.max(2,Math.round(minutes*.3)),copy:due.length?due.length+' item'+(due.length===1?' is':'s are')+' ready now.':'Begin with familiar material.'},{label:weakLabel?'Focus on '+weakLabel:'Core training',minutes:Math.max(2,Math.round(minutes*.5)),copy:weakLabel?'Work on the skill slowing you down.':'Build the course skill directly.'},{label:'Quick finish',minutes:Math.max(1,minutes-Math.round(minutes*.3)-Math.round(minutes*.5)),copy:'Save the result and schedule the next review.'}]};}

function addProgressNavigation(){const links=document.querySelector('.nav-links');if(!links)return;if(!links.querySelector('[data-progress-link]')){const link=document.createElement('a');link.href=absolute('progress/');link.textContent='My plan';link.dataset.progressLink='true';links.appendChild(link);}if(!links.querySelector('[data-roadmap-link]')){const map=document.createElement('a');map.href=absolute('roadmap/');map.textContent='Roadmap';map.dataset.roadmapLink='true';links.appendChild(map);}}
function renderCoachHome(){const host=document.querySelector('[data-coach-home]');if(!host)return;const state=loadState();if(!state.assessment){host.innerHTML='<div class="coach-status"><span class="coach-step">YOUR FIRST STEP</span><strong>Find your starting point</strong><p>Answer three setup questions, then complete a short DraMap level check.</p></div><a class="button red coach-primary" href="'+absolute('assessment/')+'"><span>Start free assessment</span><small>About 3 minutes · no account</small></a>';return;}document.body.classList.add('has-study-plan');const plan=dailyPlan(state),route=plan.route,count=(state.sessions||[]).length,streak=state.learning?.streak?.count||0,label=plan.comeback?'WELCOME BACK · 3 MIN RESTART':plan.due.length?'REVIEW READY · '+plan.due.length+' ITEM'+(plan.due.length===1?'':'S'):'TODAY · '+plan.minutes+' MIN · '+streak+' DAY CHAIN';const hero=document.querySelector('.hero');if(hero){const eyebrow=hero.querySelector('.eyebrow'),heading=hero.querySelector('h1'),lead=hero.querySelector('.lead');if(eyebrow)eyebrow.textContent='Your Japanese coach';if(heading)heading.textContent='Today\'s Japanese is ready.';if(lead)lead.textContent='One short plan based on your level, your results and what is ready for review.';}host.innerHTML='<div class="coach-status"><span class="coach-step">'+label+'</span><strong>'+route.title+'</strong><p>'+plan.why+'</p></div><a class="button red coach-primary" href="'+absolute(route.href)+(route.mode==='review'?'?review=1':'')+'"><span>'+(plan.comeback?'Restart with 3 minutes':route.mode==='review'?'Start due review':'Start today\'s plan')+'</span><small>One tap · '+count+' session'+(count===1?'':'s')+' saved</small></a>';const detail=document.createElement('section');detail.className='today-prescription';detail.innerHTML='<div class="today-prescription-head"><div><span class="coach-step">YOUR '+plan.minutes+' MINUTE PLAN</span><h2>Do these in order</h2></div><a href="'+absolute('roadmap/')+'">View roadmap</a></div><div class="today-steps">'+plan.steps.map((step,index)=>'<article><b>0'+(index+1)+'</b><span><strong>'+step.label+'</strong><small>'+step.copy+'</small></span><em>'+step.minutes+'m</em></article>').join('')+'</div><div class="habit-cue"><span><b>Make starting automatic.</b> Open this page after your usual '+(state.habitCue||'daily break')+'.</span><button type="button" data-cue>Set my cue</button></div>';host.insertAdjacentElement('afterend',detail);detail.querySelector('[data-cue]').addEventListener('click',()=>showCuePicker(state));}

function showCuePicker(state){const overlay=document.createElement('div');overlay.className='coach-modal';overlay.innerHTML='<section><span class="coach-step">YOUR DAILY CUE</span><h2>When is opening this site easiest?</h2><p>Keep your normal routine. Attach Japanese to something you already do.</p><div class="cue-options"><button data-cue-value="morning coffee">After morning coffee</button><button data-cue-value="lunch break">After lunch</button><button data-cue-value="commute">During my commute</button><button data-cue-value="evening wind-down">Before relaxing at night</button></div><button class="modal-close" data-close>Not now</button></section>';document.body.appendChild(overlay);overlay.querySelectorAll('[data-cue-value]').forEach(button=>button.addEventListener('click',()=>{state.habitCue=button.dataset.cueValue;saveState(state);location.reload();}));overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());}

const roadmapLevels=[
  {name:'Foundation',courses:['hiragana','katakana','basic_words','foundation_grammar_reading']},
  {name:'N5',courses:['n5_kanji','n5_vocabulary','n5_grammar_reading']},{name:'N4',courses:['n4_kanji','n4_vocabulary','n4_grammar_reading']},{name:'N3',courses:['n3_kanji','n3_vocabulary','n3_grammar_reading']},{name:'N2',courses:['n2_kanji','n2_vocabulary','n2_grammar_reading']},{name:'N1',courses:['n1_kanji','n1_vocabulary','n1_grammar_reading']}
];
function renderRoadmap(){const host=document.querySelector('[data-roadmap]');if(!host)return;const state=loadState();if(!state.assessment){host.innerHTML='<article class="plan-empty"><span>STEP 1</span><h2>Find your place on the map</h2><p>Your assessment unlocks a clear starting point.</p><a class="button red" href="'+absolute('assessment/')+'">Start assessment</a></article>';return;}const estimated=state.assessment.estimatedLevel,currentName=estimated==='Hiragana'||estimated==='Katakana'?'Foundation':estimated,currentIndex=Math.max(0,roadmapLevels.findIndex(level=>level.name===currentName)),practiced=new Set((state.sessions||[]).map(session=>session.course));host.innerHTML='<div class="roadmap-summary"><span class="coach-step">CURRENT POSITION</span><h2>'+currentName+'</h2><p>Move through kanji, vocabulary and grammar at this level. Reviews may temporarily become the next priority.</p></div><div class="level-roadmap">'+roadmapLevels.map((level,index)=>'<section class="level-stop '+(index<currentIndex?'passed':index===currentIndex?'active':'future')+'"><div class="level-marker"><b>'+(index<currentIndex?'✓':index+1)+'</b><span><strong>'+level.name+'</strong><small>'+(index<currentIndex?'Earlier level checked':index===currentIndex?'Your current training zone':'Opens as your skills grow')+'</small></span></div><div class="level-courses">'+level.courses.map(id=>{const route=courseRoutes[id],done=practiced.has(id);return '<a class="'+(done?'practiced':'')+'" href="'+absolute(route.href)+'"><span>'+route.title+'</span><small>'+(done?'Practiced':'Open course')+'</small></a>';}).join('')+'</div></section>').join('')+'</div><section class="roadmap-app"><div><span class="coach-step">KEEP IT ONE TAP AWAY</span><h2>Take this route into DraMap</h2><p>Use the iPhone app for short practice outside your browser.</p></div><a class="button red" href="'+DRAMAP_URL+'">Get DraMap for iOS</a></section>';}

function renderWeeklyCoach(){const dashboard=document.querySelector('[data-progress-dashboard]');if(!dashboard||!loadState().assessment)return;const state=loadState(),sessions=(state.sessions||[]),week=sessions.filter(item=>daysSince(item.completedAt)<7),days=new Set(week.map(item=>new Date(item.completedAt).toDateString())).size,weak=weakestSkill(state),plan=dailyPlan(state),section=document.createElement('section');section.className='weekly-coach';section.innerHTML='<div><span class="coach-step">THIS WEEK</span><h2>'+days+' active day'+(days===1?'':'s')+' · '+week.length+' session'+(week.length===1?'':'s')+'</h2><p>'+(weak?'Keep '+weak[0]+' in the plan until it becomes stable.':'Your current results are stable. Continue with the planned course.')+'</p></div><div class="week-next"><b>NEXT</b><span>'+plan.route.title+'</span><a href="'+absolute('roadmap/')+'">Open roadmap</a></div>';dashboard.appendChild(section);}

function addMobileCoachNav(){if(document.querySelector('.coach-tabbar'))return;const state=loadState(),route=recommendedRoute(state),bar=document.createElement('nav');bar.className='coach-tabbar';bar.setAttribute('aria-label','Learning navigation');bar.innerHTML='<a href="'+absolute('')+'"><b>●</b><span>Today</span></a><a href="'+absolute('progress/')+'"><b>↗</b><span>My plan</span></a><a href="'+absolute(route.href)+'" class="train"><b>あ</b><span>Train</span></a><a href="'+absolute('roadmap/')+'"><b>⌁</b><span>Roadmap</span></a><a href="'+DRAMAP_URL+'"><b>▣</b><span>DraMap</span></a>';document.body.appendChild(bar);}

function addSmartAppBanner(){if(document.querySelector('meta[name="apple-itunes-app"]'))return;const meta=document.createElement('meta');meta.name='apple-itunes-app';meta.content='app-id=6761260013';document.head.appendChild(meta);}

function renderAssessment(){
  const host=document.querySelector('[data-assessment]');if(!host)return;
  let setupStep=0,questionIndex=0,correct=0,timer=20,timerId=null;const answers=[];const profile={goal:'',minutes:10,selfLevel:''};
  const setup=[
    {key:'goal',label:'What do you want Japanese for?',options:[['Daily life','daily'],['Travel in Japan','travel'],['Pass the JLPT','jlpt']]},
    {key:'minutes',label:'How much time can you usually study?',options:[['5 minutes',5],['10 minutes',10],['15 minutes',15]]},
    {key:'selfLevel',label:'Which description feels closest?',options:[["I'm starting",'new'],['I know some Japanese','some'],['I already study for the JLPT','jlpt']]}
  ];
  function progress(percent,text){host.querySelector('[data-assessment-progress]').style.width=percent+'%';host.querySelector('[data-assessment-count]').textContent=text;}
  function shell(){host.innerHTML='<div class="diagnostic-top"><span data-assessment-count></span><button type="button" class="text-button" data-restart>Start over</button></div><div class="assessment-progress"><span data-assessment-progress></span></div><section class="diagnostic-card" data-diagnostic-card></section>';host.querySelector('[data-restart]').addEventListener('click',()=>{clearInterval(timerId);setupStep=questionIndex=correct=0;answers.length=0;renderSetup();});}
  function renderSetup(){clearInterval(timerId);const item=setup[setupStep];progress((setupStep/(setup.length+placementQuestions.length))*100,'SETUP '+(setupStep+1)+' OF '+setup.length);host.querySelector('[data-diagnostic-card]').innerHTML='<div class="eyebrow">Build your study plan</div><h2>'+item.label+'</h2><div class="diagnostic-choices">'+item.options.map(([label,value])=>'<button class="diagnostic-choice" data-value="'+value+'"><span>'+label+'</span><b>›</b></button>').join('')+'</div>';host.querySelectorAll('[data-value]').forEach(button=>button.addEventListener('click',()=>{profile[item.key]=item.key==='minutes'?Number(button.dataset.value):button.dataset.value;setupStep+=1;setupStep<setup.length?renderSetup():renderTestIntro();}));}
  function renderTestIntro(){progress((setup.length/(setup.length+placementQuestions.length))*100,'LEVEL CHECK');host.querySelector('[data-diagnostic-card]').innerHTML='<div class="eyebrow">DraMap placement test</div><h2>Now check what you can recognize.</h2><p class="diagnostic-lead">Eight questions move from Hiragana to N1. Each has a 20-second limit. It is fine not to know an answer.</p><button class="button red diagnostic-start" type="button">Start level check</button>';host.querySelector('.diagnostic-start').addEventListener('click',renderQuestion);}
  function renderQuestion(){if(questionIndex>=placementQuestions.length)return finish();const item=placementQuestions[questionIndex];timer=20;progress(((setup.length+questionIndex)/(setup.length+placementQuestions.length))*100,'QUESTION '+(questionIndex+1)+' OF '+placementQuestions.length+' · '+item.level.toUpperCase());host.querySelector('[data-diagnostic-card]').innerHTML='<div class="diagnostic-question-head"><span>'+item.prompt+'</span><b data-timer>20s</b></div><div class="diagnostic-context">'+item.context+'</div><div class="diagnostic-choices">'+item.choices.map(value=>'<button class="diagnostic-choice" data-answer="'+value+'"><span>'+value+'</span><b>›</b></button>').join('')+'</div>';const startedAt=Date.now();timerId=setInterval(()=>{timer-=1;const el=host.querySelector('[data-timer]');if(el)el.textContent=timer+'s';if(timer<=0)selectAnswer('',startedAt);},1000);host.querySelectorAll('[data-answer]').forEach(button=>button.addEventListener('click',()=>selectAnswer(button.dataset.answer,startedAt)));}
  function selectAnswer(value,startedAt){clearInterval(timerId);const item=placementQuestions[questionIndex];const isCorrect=value===item.answer;if(isCorrect)correct+=1;answers.push({level:item.level,skill:item.skill,correct:isCorrect,responseMs:Date.now()-startedAt});host.querySelectorAll('[data-answer]').forEach(button=>{button.disabled=true;if(button.dataset.answer===item.answer)button.classList.add('correct');else if(button.dataset.answer===value)button.classList.add('wrong');});setTimeout(()=>{questionIndex+=1;renderQuestion();},650);}
  function finish(){progress(100,'YOUR STARTING PLAN');const reachedIndex=Math.max(0,Math.min(routesOrder.length-1,Math.floor((correct/placementQuestions.length)*routesOrder.length)));const estimatedLevel=routesOrder[reachedIndex],route=routes[estimatedLevel],skills={};answers.forEach(a=>{const s=skills[a.skill]||(skills[a.skill]={correct:0,total:0});s.total++;if(a.correct)s.correct++;});const state=loadState();state.profile=profile;state.assessment={estimatedLevel,recommendedCourse:route.course,correct,total:placementQuestions.length,confidence:Math.round((.5+Math.abs(correct/placementQuestions.length-.5))*100),skills,completedAt:new Date().toISOString()};saveState(state);try{localStorage.setItem(LEGACY_PROGRESS_KEY,JSON.stringify({title:'Start at '+estimatedLevel,body:route.reason,href:absolute(route.href),completedAt:state.assessment.completedAt}));}catch(_){}host.querySelector('[data-diagnostic-card]').innerHTML='<div class="result-level"><span>RECOMMENDED START</span><strong>'+estimatedLevel+'</strong></div><div class="result-copy"><h2>'+route.title+'</h2><p>'+route.reason+'</p><div class="result-facts"><span><b>'+correct+'/'+placementQuestions.length+'</b> correct</span><span><b>'+profile.minutes+' min</b> daily plan</span><span><b>Saved</b> on this device</span></div><a class="button red coach-primary" href="'+absolute(route.href)+'"><span>Start my first session</span><small>'+profile.minutes+'-minute plan</small></a><a class="text-link" href="'+absolute('progress/')+'">See my complete plan</a></div>';}
  shell();renderSetup();
}

function renderProgressDashboard(){const dashboard=document.querySelector('[data-progress-dashboard]');if(!dashboard)return;const state=loadState();if(!state.assessment){dashboard.innerHTML='<article class="plan-empty"><span>STEP 1</span><h2>Build your personal route</h2><p>Take the DraMap placement test and receive one clear starting course.</p><a class="button red" href="'+absolute('assessment/')+'">Start assessment</a></article>';return;}const route=recommendedRoute(state),score=Math.round((state.assessment.correct/state.assessment.total)*100),sessions=(state.sessions||[]).length,due=dueRecords(state),weak=weakestSkill(state),streak=state.learning?.streak?.count||0,courseValues=Object.values(state.learning?.courses||{}),attempts=courseValues.reduce((sum,item)=>sum+(item.attempts||0),0),correct=courseValues.reduce((sum,item)=>sum+(item.correct||0),0),accuracy=attempts?Math.round(correct*100/attempts):null,weakLabel=weak?weak[0].replace(/^./,value=>value.toUpperCase()):'Collecting data',weakAccuracy=weak?Math.round(weak[1].correct*100/weak[1].attempts):null;dashboard.innerHTML='<section class="plan-today"><div><span class="coach-step">'+(due.length?'REVIEW READY NOW':'TODAY · '+todayMinutes(state)+' MINUTES')+'</span><h2>'+route.title+'</h2><p>'+route.reason+'</p></div><a class="button gold coach-primary" href="'+absolute(route.href)+(route.mode==='review'?'?review=1':'')+'"><span>'+(due.length?'Start '+due.length+' due review'+(due.length===1?'':'s'):'Start today\'s session')+'</span><small>'+(due.length?'Strengthen it before it fades':'Continue your recommended route')+'</small></a></section><section class="plan-overview"><article><span>DAILY CHAIN</span><strong>'+streak+' day'+(streak===1?'':'s')+'</strong><p>'+sessions+' completed session'+(sessions===1?'':'s')+'</p></article><article><span>TRAINING ACCURACY</span><strong>'+(accuracy===null?'—':accuracy+'%')+'</strong><p>'+(attempts?attempts+' answers measured':'Complete a training set to begin')+'</p></article><article><span>NEXT REVIEW</span><strong>'+(due.length?due.length+' ready':'On schedule')+'</strong><p>10 min · 1 d · 3 d · 7 d spacing</p></article></section><section class="coach-insight"><div><span class="coach-step">COACH INSIGHT</span><h2>'+(weak?'Focus on '+weakLabel:'Your coach is learning with you')+'</h2><p>'+(weak?'Your measured '+weakLabel.toLowerCase()+' accuracy is '+weakAccuracy+'%. The next plan will keep this skill in the loop until it becomes stable.':'Answer inside a course and the plan will identify your weakest skill automatically.')+'</p></div><strong>'+(weak?weakAccuracy+'%':'START')+'</strong></section><section class="plan-roadmap"><div class="roadmap-item done"><b>1</b><span><strong>Placement complete</strong><small>'+state.assessment.estimatedLevel+' starting point · '+score+'% score</small></span></div><div class="roadmap-item current"><b>2</b><span><strong>'+route.title+'</strong><small>'+(due.length?'Spaced review is the priority now':'Current training focus')+'</small></span></div><div class="roadmap-item"><b>3</b><span><strong>Automatic review</strong><small>Misses return sooner; stable answers wait longer</small></span></div><div class="roadmap-item app"><b>4</b><span><strong>Continue in DraMap</strong><small>Keep Japanese one tap away on iPhone</small></span><a href="'+DRAMAP_URL+'">Get the app</a></div></section>';}
function enhanceCourseCatalog(){const main=document.querySelector('main');if(!main||!document.querySelector('.course-levels'))return;const state=loadState(),route=recommendedRoute(state),guide=document.createElement('section');guide.className='catalog-guide wrap';guide.innerHTML=state.assessment?'<div><span class="coach-step">YOUR RECOMMENDED START</span><h2>'+route.title+'</h2><p>'+route.reason+'</p></div><a class="button red coach-primary" href="'+absolute(route.href)+'"><span>Continue my plan</span><small>One clear next step</small></a>':'<div><span class="coach-step">NOT SURE WHERE TO START?</span><h2>Let DraMap choose your first course.</h2><p>A short placement test turns this full catalog into one personal route.</p></div><a class="button red coach-primary" href="'+absolute('assessment/')+'"><span>Find my level</span><small>About 3 minutes</small></a>';main.querySelector('.page-hero')?.insertAdjacentElement('afterend',guide);}
function addGlobalPromotionDock(){if(document.querySelector('.global-promo-dock'))return;const promoStyles=document.createElement('link');promoStyles.rel='stylesheet';promoStyles.href=new URL('promo.css?v=2026102104',scriptUrl).href;document.head.appendChild(promoStyles);const dock=document.createElement('aside');dock.className='global-promo-dock';dock.setAttribute('aria-label','Continue Japanese in DraMap');dock.innerHTML='<div class="promo-person"><span class="promo-app-icon">あ</span><span><strong>DraMap for iOS</strong><small>Your Japanese, one tap away</small></span></div><div class="promo-actions"><a class="promo-dramap" href="'+DRAMAP_URL+'" target="_blank" rel="noopener noreferrer"><span>CONTINUE IN THE APP</span><strong>Get DraMap ↗</strong></a></div>';document.body.appendChild(dock);}
